#!/usr/bin/env bash
# ============================================================================
# Patch: ازالة نظام التحقق من حالة الحوالة (يدوي وتلقائي) + قراءة الاشعارات/SMS
# ============================================================================
# ماذا يفعل:
#   - يحول سجل العمليات الى سجل تنفيذ بحت (بدون نجاح/فشل/قيد المعالجة).
#   - يزيل شاشة "نتيجة العملية" (الخطوة 3) ويرجع فوراً للرئيسية بعد التحويل.
#   - يزيل مودال "تأكيد النتيجة اليدوي" بالكامل.
#   - خيارات الضغط على عملية بالسجل تصبح فقط: اعادة التحويل / حذف (بدون تاكيد).
#   - يحذف نهائياً: NotificationCapturePlugin.java و SwiftPayNotificationListener.java
#     وكل استدعاءاتهما وتسجيلهما وحقن صلاحية BIND_NOTIFICATION_LISTENER_SERVICE
#     بالمانيفست عبر install-stage2.sh (مصدر الحقن الفعلي، وليس android/ المُولّد).
#   - يبقي السطر الاول للاشعارات العام "appSettings.notifications" كما هو.
#   - لا يمس: UssdPlugin.java/.kt، SecurePrefsPlugin.java، ميزة رصيد جوال بي،
#     او اي تصميم/CSS.
#
# الاستخدام:
#   ./remove_status_verification.sh [مسار المشروع]
#   افتراضياً: المجلد الحالي (شغله من جذر مشروع SwiftPay، فيه www/ و native-stage2/)
#
# Idempotent: تشغيله مرتين ينتج نفس النتيجة بالضبط (استبدال كامل للملفات + rm -f).
# نسخ احتياطية .bak.<timestamp> تُنشأ تلقائياً لكل ملف قبل استبداله.
# ============================================================================
set -euo pipefail
ROOT="${1:-$(pwd)}"
TS="$(date +%s)"

for rel in www/js/app.js www/index.html native-stage2/install-stage2.sh; do
  [ -f "$ROOT/$rel" ] || { echo "خطأ: لم يتم العثور على $ROOT/$rel — تاكد انك بجذر مشروع SwiftPay الصحيح."; exit 1; }
done

echo "==> نسخ احتياطية..."
mkdir -p "$ROOT/docs/patches/backup_$TS"
cp "$ROOT/www/js/app.js" "$ROOT/docs/patches/backup_$TS/app.js.bak"
cp "$ROOT/www/index.html" "$ROOT/docs/patches/backup_$TS/index.html.bak"
cp "$ROOT/native-stage2/install-stage2.sh" "$ROOT/docs/patches/backup_$TS/install-stage2.sh.bak"

echo "==> كتابة www/js/app.js ..."
B64_www_js_app_js=""
mkdir -p "$(dirname "$ROOT/www/js/app.js")"
echo "$B64_www_js_app_js" | base64 -d > "$ROOT/www/js/app.js"

echo "==> كتابة www/index.html ..."
B64_www_index_html=""
mkdir -p "$(dirname "$ROOT/www/index.html")"
echo "$B64_www_index_html" | base64 -d > "$ROOT/www/index.html"

echo "==> كتابة native-stage2/install-stage2.sh ..."
B64_native_stage2_install_stage2_sh=""
mkdir -p "$(dirname "$ROOT/native-stage2/install-stage2.sh")"
echo "$B64_native_stage2_install_stage2_sh" | base64 -d > "$ROOT/native-stage2/install-stage2.sh"

echo "==> حذف الملفات الميتة (اصبحت غير مستخدمة نهائياً)..."
rm -f "$ROOT/native-stage2/SwiftPayNotificationListener.java"
rm -f "$ROOT/native-stage2/NotificationCapturePlugin.java"

echo "==> فحص صحة app.js..."
if command -v node >/dev/null 2>&1; then
  node --check "$ROOT/www/js/app.js" && echo "    app.js: syntax OK"
else
  echo "    (node غير متوفر بالبيئة الحالية — تخطي الفحص)"
fi

echo ""
echo "تم بنجاح. الملفات المعدّلة:"
echo "  - www/js/app.js"
echo "  - www/index.html"
echo "  - native-stage2/install-stage2.sh"
echo "الملفات المحذوفة:"
echo "  - native-stage2/SwiftPayNotificationListener.java"
echo "  - native-stage2/NotificationCapturePlugin.java"
echo ""
echo "ملاحظة: اذا كان مجلد android/ موجوداً ومبنياً مسبقاً بخدمة الاشعارات"
echo "(نتيجة تشغيل install-stage2.sh قديم)، يُنصح بحذفه واعادة توليده:"
echo "  rm -rf android && npx cap add android && ./native-stage2/install-stage2.sh"
